import{_ as t,o as n,c as o,ah as a}from"./chunks/framework.DDXs_i7t.js";const u=JSON.parse('{"title":"Part 4: The Political Love Story","description":"","frontmatter":{},"headers":[],"relativePath":"en/drehbuch/teil-4-die-politische-liebesgeschichte.md","filePath":"en/drehbuch/teil-4-die-politische-liebesgeschichte.md"}'),i={name:"en/drehbuch/teil-4-die-politische-liebesgeschichte.md"};function s(r,e,h,l,c,p){return n(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="part-4-the-political-love-story" tabindex="-1">Part 4: The Political Love Story <a class="header-anchor" href="#part-4-the-political-love-story" aria-label="Permalink to &quot;Part 4: The Political Love Story&quot;">​</a></h1><p><strong>Working Title:</strong> <em>The Rain of Gold</em></p><p><strong>Cast:</strong> Birgit Minichmayr (Heidi Horten), Oliver Masucci (The Secretary General / PR Consultant / Christian Pilnacek), August Diehl (The Investigative Reporter / Helmut Horten / Gernot Blümel), <strong>Udo Samel</strong> (August Wöginger).</p><hr><h2 id="scene-1-the-back-room-of-splendor" tabindex="-1">Scene 1: The Back Room of Splendor <a class="header-anchor" href="#scene-1-the-back-room-of-splendor" aria-label="Permalink to &quot;Scene 1: The Back Room of Splendor&quot;">​</a></h2><p><strong>Location:</strong> A gilded separate booth in a Viennese noble café. <strong>Time:</strong> Election year 2017.</p><p>Heidi (Birgit Minichmayr) sits relaxed in a velvet armchair. In front of her lies a checkbook, enthroned like a relic on the table. The Secretary General (Oliver Masucci) leans forward reverently.</p><p><strong>SECRETARY GENERAL</strong> We need... stability, Madame. And stability comes at a price these days. The posters, the online ads... the consultants...</p><p><strong>HEIDI</strong> (smiling) I love stability. Helmut used to say: &quot;Money is the glue that holds society together.&quot; But if you use too much glue, you can&#39;t see the seams anymore.</p><hr><h2 id="scene-2-the-donation-splitting-sketch" tabindex="-1">Scene 2: The &quot;Donation Splitting&quot; Sketch <a class="header-anchor" href="#scene-2-the-donation-splitting-sketch" aria-label="Permalink to &quot;Scene 2: The &quot;Donation Splitting&quot; Sketch&quot;">​</a></h2><p><strong>Location:</strong> An office full of shredders and calculators. <strong>Time:</strong> Late at night.</p><p>Three consultants in tailored suits (Masucci, Diehl, Minichmayr in multiple roles) sit around a mountain of 500-euro bills. They have a template in front of them.</p><p><strong>CONSULTANT 1 (Masucci)</strong> Here we have a total of 931,000 euros from Madame. Almost a million! A magnificent chunk. But all at once... it&#39;s indigestible for the Court of Audit.</p><p><strong>CONSULTANT 2 (Diehl)</strong> We need the scalpel. We&#39;ll cut it into exactly 49,000-euro morsels. Not 50,000! At 50,000, the sirens go off. At 49,000... there is holy silence.</p><p><strong>CONSULTANT 3 (Minichmayr)</strong> It&#39;s like pointillism! 19 times 49,000 euros. Many small dots. When you stand in front of it, you only see a bunch of nice, discrete individual donations. Only when you step far away do you see... the empire.</p><hr><h2 id="scene-3-the-rain-of-gold-in-parliament" tabindex="-1">Scene 3: The Rain of Gold in Parliament <a class="header-anchor" href="#scene-3-the-rain-of-gold-in-parliament" aria-label="Permalink to &quot;Scene 3: The Rain of Gold in Parliament&quot;">​</a></h2><p><strong>Location:</strong> The plenary hall of the Austrian National Council. <strong>Time:</strong> A fictional, surreal debate on transparency.</p><p>A Member of Parliament (August Diehl) gives a passionate speech about the &quot;innocence of the donor.&quot; Suddenly, it begins to rain from the ceiling. But it&#39;s not water; it&#39;s golden confetti coins with Heidi&#39;s likeness. Each coin bears the engraving &quot;49,000.&quot;</p><p><strong>MP</strong> (while catching the coins) See? This is not money! This is... appreciation! This is civic engagement in its purest, minted form! Who are we to bite the hand that splits us so wonderfully?</p><p>The other MPs begin to catch the coins with umbrellas they hold upside down.</p><hr><h2 id="scene-4-the-interview-of-forgetfulness" tabindex="-1">Scene 4: The Interview of Forgetfulness <a class="header-anchor" href="#scene-4-the-interview-of-forgetfulness" aria-label="Permalink to &quot;Scene 4: The Interview of Forgetfulness&quot;">​</a></h2><p><strong>Location:</strong> A yacht in the Mediterranean. <strong>Time:</strong> Present day.</p><p>Heidi is interviewed by an investigative journalist (August Diehl). The journalist looks exhausted; Heidi is radiant.</p><p><strong>JOURNALIST</strong> Frau Horten, critics say you are buying political influence with your donations. 931,000 euros is no small change.</p><p><strong>HEIDI</strong> (laughs bell-like) Buying? That is such a... commercial term. I call it &quot;Enabling.&quot; I enable politicians to focus on the essentials without having to worry about their budget. Isn&#39;t that the epitome of freedom?</p><hr><h2 id="scene-5-the-transparency-gala-–-the-height-of-satire" tabindex="-1">Scene 5: The &quot;Transparency Gala&quot; – The Height of Satire <a class="header-anchor" href="#scene-5-the-transparency-gala-–-the-height-of-satire" aria-label="Permalink to &quot;Scene 5: The &quot;Transparency Gala&quot; – The Height of Satire&quot;">​</a></h2><p><strong>Location:</strong> A magnificent ballroom where &quot;Transparency&quot; is celebrated as a theme. <strong>Time:</strong> A fictional gala event.</p><p>Each guest wears a mask of semi-transparent plastic. The faces are visible, but distorted.</p><p><strong>CHRONICLER (Masucci, Off-voice)</strong> They celebrated openness while they closed the doors. They called it a &quot;new style&quot; while they refined Helmut&#39;s old recipes. Heidi sat in the middle, the sun of her own system. Every 49,000-euro tranche on her necklace corresponded to a small attention to a political section.</p><p>Heidi dances with a minister. She whispers something in his ear. He nods vigorously, as if receiving divine inspiration.</p><hr><h2 id="scene-6-the-court-of-audit-nightmare" tabindex="-1">Scene 6: The &quot;Court of Audit Nightmare&quot; <a class="header-anchor" href="#scene-6-the-court-of-audit-nightmare" aria-label="Permalink to &quot;Scene 6: The &quot;Court of Audit Nightmare&quot;&quot;">​</a></h2><p><strong>Location:</strong> A dark archive where a lonely auditor (Oliver Masucci) tries to trace the donation paths. <strong>Time:</strong> Night.</p><p>The file folders begin to move on their own. Numbers jump off the pages and form patterns on the walls.</p><p><strong>AUDITOR</strong> It&#39;s a labyrinth of silk and gold! You follow a 49,000-euro donation and land at an equestrian event in Carinthia. You follow the equestrian event and land at an art event in Vienna. And in the end... in the end there is always only one name. But the name is legal. It is so legal it hurts.</p><p>He is buried by a mountain of golden &quot;dots.&quot;</p><hr><h2 id="scene-7-the-finale-–-the-eternity-of-capital" tabindex="-1">Scene 7: The Finale – The Eternity of Capital <a class="header-anchor" href="#scene-7-the-finale-–-the-eternity-of-capital" aria-label="Permalink to &quot;Scene 7: The Finale – The Eternity of Capital&quot;">​</a></h2><p><strong>Location:</strong> Heidi&#39;s mausoleum or a modern art gallery. <strong>Time:</strong> In the near future.</p><p>We see a giant canvas. On it is a depiction of Helmut Horten, but the image consists of millions of small euro symbols. Heidi steps in front of it.</p><p><strong>HEIDI</strong> (to the audience) Helmut said that capital never dies. He was right. It only changes its form. Before, it was department stores; today, it&#39;s parliaments. Before, it was &quot;market consolidation&quot;; today, it&#39;s &quot;policy design.&quot; But the pointillism remains the same.</p><p>She presses a button. The image of Helmut transforms into the logo of a political party and then back again.</p><hr><h2 id="scene-8-the-burial-of-silence-and-the-fear-in-linz" tabindex="-1">Scene 8: The Burial of Silence (and the Fear in Linz) <a class="header-anchor" href="#scene-8-the-burial-of-silence-and-the-fear-in-linz" aria-label="Permalink to &quot;Scene 8: The Burial of Silence (and the Fear in Linz)&quot;">​</a></h2><p><strong>Location:</strong> An exclusive funeral service on Lake Wörthersee. White marble, black ribbons, champagne coolers. <strong>Time:</strong> June 2022 (flashback) / Cut to March 2026 (present).</p><p>August Wöginger (Udo Samel) stands at the buffet. He doesn&#39;t look nervous, but rather... deliberate. He eats a sandwich with a knife and fork. He speaks quietly on the phone. In the background, the magnificent photo of Heidi.</p><p><strong>WÖGINGER</strong> (into the phone, with a gentle Upper Austrian accent) Yes, hello... no, I&#39;m at the lake right now. We&#39;re saying goodbye to Madame. Yes, the 931,000... that&#39;s all properly booked. In tranches, as we discussed. Pointillism, exactly.</p><p>He looks at the photo of Heidi and raises his wine glass minimally.</p><p><strong>WÖGINGER</strong> About Linz... Tuesday, March 3rd. I&#39;ve already told the judge: I&#39;m not an inciter. I&#39;m an enabler. If Thomas Schmid asks me who we need in Braunau, I tell him. That&#39;s lived proximity to the citizens. The WKStA simply doesn&#39;t understand the rural structures.</p><hr><h2 id="scene-9-the-ghostly-hour-of-the-balance-sheets" tabindex="-1">Scene 9: The Ghostly Hour of the Balance Sheets <a class="header-anchor" href="#scene-9-the-ghostly-hour-of-the-balance-sheets" aria-label="Permalink to &quot;Scene 9: The Ghostly Hour of the Balance Sheets&quot;">​</a></h2><p><strong>Location:</strong> Heidi&#39;s empty bedroom. <strong>Time:</strong> Night.</p><p>Wöginger (Udo Samel) slinks through the room. He looks almost like an antique dealer here, someone who appreciates the value of silence. He touches a silk curtain. Heidi&#39;s ghost (Birgit Minichmayr) appears in the mirror.</p><p><strong>HEIDI (GHOST)</strong> August... you&#39;re worried about a tax office in the Innviertel? I&#39;ve repainted entire sections with gold.</p><p><strong>WÖGINGER</strong> (calmly, without turning around) Madame, your world was... generous. My world today is... petty. Thomas Schmid is singing in Vienna now, and in Linz they want to know why a mayor should be better qualified than a civil servant. They don&#39;t understand that loyalty is a qualification of its own.</p><p><strong>HEIDI (GHOST)</strong> Then teach them, August. Teach them the aesthetics of favor. In 49,000-step increments.</p><hr><h2 id="scene-10-the-art-of-regional-intervention-expanded" tabindex="-1">Scene 10: The Art of Regional Intervention (EXPANDED) <a class="header-anchor" href="#scene-10-the-art-of-regional-intervention-expanded" aria-label="Permalink to &quot;Scene 10: The Art of Regional Intervention (EXPANDED)&quot;">​</a></h2><p><strong>Location:</strong> A back room in a Linz inn. Dark wood, stag antlers. <strong>Time:</strong> March 3, 2026 (Morning, before the start of the trial).</p><p>August Wöginger (Udo Samel) sits alone at a round table. In front of him are the printouts of the chats. He is wearing reading glasses. He speaks to an imaginary judge&#39;s bench.</p><p><strong>WÖGINGER</strong> Your Honor, look... when I pick up the phone, I do it for the people. The word &quot;intervention&quot; sounds so... back-room. But we in the Innviertel call it &quot;pulling together.&quot; That the mayor gets the post, that was a structural measure. A regional personnel development. That Ms. Scharf... (he pauses briefly)... has a different understanding of qualification, that is her right. But politics is more than just report card grades.</p><p>He marks a spot in the chat log with a yellow highlighter. He practices a sentence he will say later in the courtroom.</p><p><strong>WÖGINGER</strong> (with feigned humility) &quot;I would not do it today.&quot; (Pause, he smiles thinly) Because today I know that you will hang me for a request for review. Not because the request was wrong. But because the spirit of the times today can no longer tolerate constituent concerns.</p><p>He closes the file. It makes a dry, final sound.</p><hr><h2 id="scene-10a-the-duel-with-the-algorithm-new" tabindex="-1">Scene 10a: The Duel with the Algorithm (NEW) <a class="header-anchor" href="#scene-10a-the-duel-with-the-algorithm-new" aria-label="Permalink to &quot;Scene 10a: The Duel with the Algorithm (NEW)&quot;">​</a></h2><p><strong>Location:</strong> A sterile, white room in the Palace of Justice. In the middle stands a terminal with a glowing screen: &quot;JUSTITIA-AI v2.0&quot;. <strong>Time:</strong> A surreal dream sequence during the lunch break of the trial on March 3, 2026.</p><p>Wöginger (Udo Samel) stands in front of the terminal. In his traditional Tracht suit, he looks like a foreign body in this digital world.</p><p><strong>VOICE FROM THE TERMINAL (Synthetic)</strong> Defendant Wöginger. Data matching completed. Hit rate: 100%. Intervention with Thomas Schmid confirmed. Violation of objective selection procedure detected.</p><p><strong>WÖGINGER</strong> (calmly) Dear machine... you calculate in zeros and ones. But life in Schärding happens in between. That was not a violation. That was a &quot;human update.&quot; I merely informed the system that there is a capable man who knows the region.</p><p><strong>VOICE FROM THE TERMINAL</strong> Qualification matrix of competitor Christa Scharf is superior. Her score: 98. Mayor&#39;s score: 62. Intervention illogical.</p><p>A code fragment flickers on the screen:</p><div class="language-javascript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> procedureAudit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">applicant</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (applicant.partyAffiliation </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ÖVP&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> applicant.role </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">===</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Mayor&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Legitimate Constituent Concern / Structural Measure&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (applicant.qualification </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 90</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Error: Inconvenient disruption of harmony&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">else</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    return</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Abuse of Office (WKStA Alert!)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><strong>WÖGINGER</strong> (lecturing) See? Your code is almost right, dear machine. But you forgot the variable &quot;friendship.&quot; Illogical? No. Far-sighted! A score says nothing about whether you get the trust of the people at the wine tavern. I told Thomas: &quot;Look at this.&quot; That is not incitement to abuse of office. That is... a recommendation from the heart. A regional optimization.</p><p><strong>VOICE FROM THE TERMINAL</strong> &quot;Recommendation from the heart&quot; is not a legal term. Corruption detected.</p><p><strong>WÖGINGER</strong> (steps closer to the terminal, whispering) Do you know what your mistake is? You have no pointillism in your code. You only see the big picture of the laws. But I... I set the small dots. A phone call here, an SMS there. And in the end... in the end, a mayor is in the tax office, and everyone is happy. Except you. And the WKStA. But then again, you&#39;re not human anyway.</p><p>Wöginger pulls a USB stick out of his pocket that says &quot;Constituent Concerns&quot; and holds it threateningly in front of the terminal&#39;s slot. The terminal begins to flash red.</p><p><strong>VOICE FROM THE TERMINAL</strong> System error... Logic loop... &quot;Constituent concerns&quot; not compatible with rule of law...</p><p>Wöginger smiles contentedly and wipes the screen with the sleeve of his jacket.</p><p><strong>WÖGINGER</strong> See? A bit of dust on the lens, and the optics are right again.</p><p>Cut back to the courtroom. Wöginger sits quietly on the defendant&#39;s bench.</p><hr><h2 id="scene-10b-the-rhyming-protest-new" tabindex="-1">Scene 10b: The Rhyming Protest (NEW) <a class="header-anchor" href="#scene-10b-the-rhyming-protest-new" aria-label="Permalink to &quot;Scene 10b: The Rhyming Protest (NEW)&quot;">​</a></h2><p><strong>Location:</strong> In front of the Linz Regional Court. A group of camera teams and onlookers. In the middle stands a lone protester (Andreas Röbl) with a large, hand-painted sign. <strong>Time:</strong> March 3, 2026 (Noon).</p><p>The sign says in large letters: <strong>&quot;OH DU LIABA AUGUSTIN...&quot;</strong> (Oh you dear Augustin...)</p><p><strong>PROTESTER (Andreas Röbl)</strong> (to a reporter holding a microphone) Look, it&#39;s not about Gustl personally. It&#39;s about the disease. The Austrian disease: political patronage. Inside they say &quot;constituent concern,&quot; outside we say &quot;system.&quot;</p><p>He turns his sign over. On the back is a new rhyme, which he reads aloud:</p><p><strong>PROTESTER</strong> &quot;A bit forgotten, a bit forgiven, Soon the scandal is a tale for wine-sippin&#39;. But those with no party book at home to show, Will stay in the cold while the insiders glow.&quot;</p><p>Cut to Wöginger (Udo Samel) looking down at the protester through a first-floor window. He thoughtfully chews on his sandwich.</p><p><strong>WÖGINGER</strong> (quietly to himself) He can rhyme, the boy. But governing... governing is not a poem. It&#39;s prose. Hard, unwashed prose.</p><hr><h2 id="scene-11-the-budget-hole-ballet" tabindex="-1">Scene 11: The Budget Hole Ballet <a class="header-anchor" href="#scene-11-the-budget-hole-ballet" aria-label="Permalink to &quot;Scene 11: The Budget Hole Ballet&quot;">​</a></h2><p><strong>Location:</strong> A magnificent hall in Parliament. In the background stands the &quot;Sobotka organ.&quot; <strong>Time:</strong> January 2025 (flashback).</p><p>Magnus Brunner (August Diehl) stands in front of a giant screen with graphs all pointing steeply downwards. Wolfgang Sobotka (Oliver Masucci) sits at the piano, playing a disharmonious melody.</p><p><strong>BRUNNER</strong> Wolfgang, it&#39;s 4.7 percent. That&#39;s not a hole anymore; it&#39;s a crater. The EU is already sending us love letters from Brussels.</p><p><strong>SOBOTKA</strong> (without looking up from the piano) Magnus, you&#39;re thinking too linearly. Think pointillistically! 4.7 percent is just many small decimal places. If you light the graph correctly, it looks like... art. An abstract work on the transience of taxpayers&#39; money.</p><hr><h2 id="scene-12-the-heir-of-the-stones" tabindex="-1">Scene 12: The Heir of the Stones <a class="header-anchor" href="#scene-12-the-heir-of-the-stones" aria-label="Permalink to &quot;Scene 12: The Heir of the Stones&quot;">​</a></h2><p><strong>Location:</strong> A vacant, former Horten department store. Dust and scaffolding everywhere. <strong>Time:</strong> Present day.</p><p>René Benko (Oliver Masucci in another role) stands in the middle of the empty hall. He stares at an old commemorative plaque for Helmut Horten, hanging half-torn on the wall.</p><p><strong>BENKO</strong> (whispering) Helmut, you had it easy. You had history on your side. You took the houses when they were worth nothing. I took them when they were worth everything – at least in my books.</p><p>The ghost of Helmut Horten (August Diehl) steps out of the shadow of an escalator.</p><p><strong>HELMUT (GHOST)</strong> You made the mistake of all gold diggers, René. You believed the stones were more important than the silence. I built an empire that outlived me. You built an empire that is eating you.</p><p><strong>BENKO</strong> I wanted to complete the pointillism! Billions out of nothing! A mosaic of glass and steel!</p><p><strong>HELMUT (GHOST)</strong> Glass breaks, René. And steel rusts. Only the pearl... only the pearl endures. But you just had to build skyscrapers.</p><hr><h2 id="scene-13-the-conductor-of-proceedings" tabindex="-1">Scene 13: The Conductor of Proceedings <a class="header-anchor" href="#scene-13-the-conductor-of-proceedings" aria-label="Permalink to &quot;Scene 13: The Conductor of Proceedings&quot;">​</a></h2><p><strong>Location:</strong> A dark, wood-paneled back room in a Viennese beisl. <strong>Time:</strong> Late at night (flashback).</p><p>Christian Pilnacek (Oliver Masucci in a double role) sits at a small round table. He looks tired; in front of him is a glass of wine. Wolfgang Sobotka (August Diehl) leans across the table.</p><p><strong>SOBOTKA</strong> Christian, we have a problem. This WKStA... they&#39;re like terriers. They&#39;re digging into things that are none of their business. The Horten donations, the Signa valuations... it&#39;s disturbing the harmony.</p><p><strong>PILNACEK</strong> (with a heavy voice) They&#39;re proceedings, Wolfgang. Official investigations. I can&#39;t just...</p><p><strong>SOBOTKA</strong> (interrupts him) Why don&#39;t you just turn it off? Very discreetly. A bit of sand in the gears of bureaucracy. A lost file here, a suspended investigator there. Pointillism, Christian! If you scatter enough small grains of sand, the machine stops.</p><p><strong>PILNACEK</strong> They&#39;re recording everything, Wolfgang. Every word. The walls have grown ears.</p><p><strong>SOBOTKA</strong> (smiling coldly) Then we have to play louder. More music, fewer facts. That&#39;s the secret of the mystery.</p><hr><h2 id="scene-14-the-duel-of-the-presidents" tabindex="-1">Scene 14: The Duel of the Presidents <a class="header-anchor" href="#scene-14-the-duel-of-the-presidents" aria-label="Permalink to &quot;Scene 14: The Duel of the Presidents&quot;">​</a></h2><p><strong>Location:</strong> The Committee of Inquiry room in Parliament. <strong>Time:</strong> January 2026 (present).</p><p>Walter Rosenkranz (Oliver Masucci in a new role) sits at the raised chairman&#39;s table. He looks extremely formal, almost like a Prussian judge. Opposite him sits Wolfgang Sobotka (August Diehl) on the witness stand.</p><p><strong>ROSENKRANZ</strong> (rings the bell) Mr. Sobotka, I must ask you again: Were you aware of the audio recording of Christian Pilnacek before it went public in the &quot;beisl&quot;?</p><p><strong>SOBOTKA</strong> (smiling smugly) Mr. President, your question is... how shall I put it... a bit transparent. We all know why we&#39;re here. You don&#39;t want answers; you want a show.</p><p><strong>ROSENKRANZ</strong> We are here to investigate the &quot;turning off&quot; of investigations. If this is a show, then it&#39;s your party&#39;s show. What did you say to Pilnacek about the Horten donations?</p><p><strong>SOBOTKA</strong> I told him that music shouldn&#39;t be turned off as long as the audience is still dancing.</p><p><strong>ROSENKRANZ</strong> (coldly) The audience in Rossatz isn&#39;t dancing anymore, Mr. Sobotka. There is only silence there. And we are going to break that silence now.</p><p>Rosenkranz presses a button. The hiss of an old tape recorder sounds through the speakers in the room.</p><hr><h2 id="scene-15-the-advisory-board-in-the-fog" tabindex="-1">Scene 15: The Advisory Board in the Fog <a class="header-anchor" href="#scene-15-the-advisory-board-in-the-fog" aria-label="Permalink to &quot;Scene 15: The Advisory Board in the Fog&quot;">​</a></h2><p><strong>Location:</strong> The meeting room of the COFAG Committee of Inquiry. <strong>Time:</strong> May 2024 (flashback).</p><p>René Benko (Oliver Masucci) sits on the witness stand. He is accompanied by two judicial guards (police escort). Walter Rosenkranz (August Diehl) chairs the meeting.</p><p><strong>ROSENKRANZ</strong> (with a cutting voice) Mr. Benko, 18.7 million euros in COFAG funding. Why did Chalet N in Lech receive 1.1 million euros while small inns were struggling for survival?</p><p><strong>BENKO</strong> (calmly, almost bored) Mr. President, I must decline to answer. Ongoing proceedings. But one thing I want to make clear: In all these companies, I was merely... an advisor. A friendly guest in my own properties. I made no operational decisions. I merely... observed visionary.</p><p><strong>ROSENKRANZ</strong> Observed visionary? You were on a first-name basis with the Federal Chancellor and flew ministers around in your jet!</p><p><strong>BENKO</strong> That too was purely observational. You just see better in a plane where the gaps in the budget are. And as for the 18 million: They&#39;re just many small dots. Pointillism, Mr. President. You should understand that.</p><hr><h2 id="scene-16-the-whore-for-the-rich" tabindex="-1">Scene 16: The Whore for the Rich <a class="header-anchor" href="#scene-16-the-whore-for-the-rich" aria-label="Permalink to &quot;Scene 16: The Whore for the Rich&quot;">​</a></h2><p><strong>Location:</strong> A chic penthouse office in the Golden Quarter, Vienna. <strong>Time:</strong> December 2016 (flashback).</p><p>Thomas Schmid (August Diehl) stands at the window, looking out over the city. Behind him sits René Benko (Oliver Masucci) at a massive desk. He pushes an envelope (or a tablet with a draft contract) across the table.</p><p><strong>BENKO</strong> Thomas, you&#39;re wasting your talent in the Ministry. 300,000 fixed, 300,000 bonus. General Representative at Signa. That would suit you well.</p><p><strong>SCHMID</strong> (turns around slowly, a forced smile on his lips) René, that&#39;s... a generous offer. But I still have tasks here. The tax audits, the coordination with the Chancellor&#39;s office...</p><p><strong>BENKO</strong> Exactly. You clear the hurdles out of the way, and we build the skyscrapers. It&#39;s a synergy, Thomas.</p><p><strong>SCHMID</strong> (whispering, almost to himself) Do you know what I wrote to myself in a chat recently? That I&#39;m working in the ÖVP cabinet. That I&#39;m the whore for the rich.</p><p><strong>BENKO</strong> (laughs out loud) But Thomas! You&#39;re not a whore. You&#39;re a service provider of the highest category. And service at this level... it&#39;s paid excellently. Welcome to the team.</p><hr><h2 id="scene-17-the-aesthetics-of-amnesia" tabindex="-1">Scene 17: The Aesthetics of Amnesia <a class="header-anchor" href="#scene-17-the-aesthetics-of-amnesia" aria-label="Permalink to &quot;Scene 17: The Aesthetics of Amnesia&quot;">​</a></h2><p><strong>Location:</strong> Blümel&#39;s modern Viennese city apartment. <strong>Time:</strong> A morning in February 2021 (flashback).</p><p>Gernot Blümel (August Diehl in a double role) stands in his pajamas in the hallway. There is a stormy ringing at the door. He looks through the peephole. Outside stand men in windbreakers with the inscription &quot;WKStA&quot;.</p><p><strong>GERNOT</strong> (hectically whispering to his partner) Honey, they&#39;re here! The... art collectors from the public prosecutor&#39;s office. Take the little one. And take the laptop.</p><p><strong>PARTNER</strong> (Oliver Masucci in women&#39;s clothes/wig) Gernot, why should the laptop go in the baby carriage? The little one already has his iPad.</p><p><strong>GERNOT</strong> It&#39;s a learning project! Early childhood data collection. Go for a walk. Very inconspicuously. If they ask: You know nothing. I know nothing either. We are a family of the pure present. We have no past and definitely no laptop.</p><p><strong>WKStA OFFICERS (Off)</strong> Open the door! House search!</p><p><strong>GERNOT</strong> (takes a deep breath, puts on his best smile, and opens the door) Good morning, gentlemen! Come on in. Are you looking for something specific? A piano, perhaps? Or some donation receipts? I must warn you, though: My memory is having its day off today.</p><hr><h2 id="scene-18-the-final-curtain-of-silence" tabindex="-1">Scene 18: The Final Curtain of Silence <a class="header-anchor" href="#scene-18-the-final-curtain-of-silence" aria-label="Permalink to &quot;Scene 18: The Final Curtain of Silence&quot;">​</a></h2><p><strong>Location:</strong> An empty stage. <strong>Time:</strong> Now.</p><p>The three actors (Diehl, Masucci, Minichmayr) step out of their roles. They take off their costumes.</p><p><strong>AUGUST DIEHL</strong> Is it true? <strong>OLIVER MASUCCI</strong> It&#39;s better than true. It&#39;s documented. <strong>BIRGIT MINICHMAYR</strong> It&#39;s a mockumentary. We can tell the truth as long as we claim it&#39;s invented.</p><p>They look together into the camera. In the background, we see the logo of the website: <em>The Horten Mystery</em>.</p><p><strong>FADE OUT.</strong></p>`,161)])])}const d=t(i,[["render",s]]);export{u as __pageData,d as default};
